def reprendre_anciens_reglages(apps, schema_editor):
    """Les trois réglages d'avant la matrice (séisme, vigilance, feux satellite) deviennent des
    règles ; les anciens sont désactivés pour ne pas prévenir deux fois."""
    RegleAlerte = apps.get_model("core", "RegleAlerte")
    reprises = (
        ("ConfigurationAlerteSismique", "SEISME", lambda c: {"alerte": c.magnitude_min, "rayon_km": c.rayon_km}),
        ("ConfigurationAlerteVigilance", "VIGILANCE_METEO", lambda c: {"alerte": c.couleur_min}),
        ("ConfigurationAlerteFeu", "FOYERS", lambda c: {"rayon_km": c.rayon_km}),
    )
    for modele, phenomene, seuils in reprises:
        for ancien in apps.get_model("core", modele).objects.all():
            RegleAlerte.objects.update_or_create(
                institution_id=ancien.institution_id, phenomene=phenomene, environment=ancien.environment,
                defaults={"actif": ancien.actif, "seuils": seuils(ancien)})
            if ancien.actif:
                ancien.actif = False
                ancien.save(update_fields=["actif"])


